(88, '(১:১) ফ্রাইড রাইস + চিকেন ফ্রাই (২ পিস) + সবজি', 'পিচ', '<p><strong>(১:১) ফ্রাইড রাইস + চিকেন ফ্রাই (২ পিস) + সবজি</strong> ক্যাফে ডি পাস্তা, কুষ্টিয়া-তে স্বাস্থ্যসম্মত ও সেরা উপাদানে প্রস্তুত। সুস্বাদু স্বাদ ও অতুলনীয় অভিজ্ঞতার জন্য আজই অর্ডার করুন।</p>', 'bd', NOW(), NOW()),
(89, '(১:১) ফ্রাইড রাইস + চিকেন কারি + সবজি', 'পিচ', '<p><strong>(১:১) ফ্রাইড রাইস + চিকেন কারি + সবজি</strong> ক্যাফে ডি পাস্তা, কুষ্টিয়া-তে স্বাস্থ্যসম্মত ও সেরা উপাদানে প্রস্তুত। সুস্বাদু স্বাদ ও অতুলনীয় অভিজ্ঞতার জন্য আজই অর্ডার করুন।</p>', 'bd', NOW(), NOW()),
(90, '(১:১) ফ্রাইড রাইস + বিফ কারি + সবজি', 'পিচ', '<p><strong>(১:১) ফ্রাইড রাইস + বিফ কারি + সবজি</strong> ক্যাফে ডি পাস্তা, কুষ্টিয়া-তে স্বাস্থ্যসম্মত ও সেরা উপাদানে প্রস্তুত। সুস্বাদু স্বাদ ও অতুলনীয় অভিজ্ঞতার জন্য আজই অর্ডার করুন।</p>', 'bd', NOW(), NOW()),
